files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #1a5bbf;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;
  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  box-sizing: border-box;
}

.nav {
  padding: 20px 0;
  position: sticky;
  top: 0;
  background: var(--vt-surface);
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
  z-index: 1000;
}

.navIn {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 100%;
  box-sizing: border-box;
  padding: 0 15px;
}

.logo {
  display: inline-block;
  color: var(--vt-accent);
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin: 0 30px;
  padding: 0;
  text-decoration: none;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 0.75rem;
  position: relative;
  bottom: 5px;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  font-weight: 600;
  font-size: 1rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  padding: 15px 0;
  text-decoration: none;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  padding-top: 0;
}

.heroSlider {
  position: relative;
  width: 100%;
  height: 580px;
  overflow: hidden;
}

.sliderTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  height: 100%;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
  margin: 0;
}

.slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-sizing: border-box;
}

.heroText h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin: 0 0 0.5rem;
  color: var(--vt-ink);
}

.heroText p {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  margin: 0 0 1rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  text-decoration: none;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  margin-left: 1rem;
  color: var(--vt-ink);
  font-size: 1rem;
}

.section {
  width: 100%;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.aboutRow {
  display: flex;
  justify-content: center;
}

.aboutContent {
  max-width: 800px;
  text-align: left;
}

.aboutContent h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.aboutContent p {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  line-height: 1.6;
}

.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 0 0 50%;
  padding: 0;
  position: relative;
  overflow: hidden;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.gallerySub {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(0, 0, 0, 0.5);
  color: var(--vt-on-deep);
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

.timelineTitle {
  text-align: center;
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  position: relative;
  margin-bottom: 3rem;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineContent {
  flex: 0 0 45%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 1.5rem;
  font-weight: 600;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 1rem;
}

.timelineNode:nth-child(odd) h3,
.timelineNode:nth-child(odd) p {
  text-align: right;
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
}

.timelineNode:nth-child(odd) h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIcon {
  flex: 0 0 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  margin: 0 1rem;
}

.timelineIcon span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1.5rem rgba(0, 0, 0, 0.15);
  color: var(--vt-accent);
  font-size: 1.5rem;
  font-weight: 700;
  z-index: 3;
}

.timelineDate {
  flex: 0 0 400px;
  padding: 1.5rem 0;
  color: var(--vt-ink-soft);
  font-size: 1rem;
}

.footer {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2rem;
}

.footerCol {
  flex: 1 1 200px;
}

.footerCol h5 {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  font-weight: 700;
}

.hoursList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.hoursList li {
  display: flex;
  justify-content: space-between;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--vt-line);
  color: var(--vt-ink-soft);
  font-size: 1rem;
}

.hoursList li:first-child {
  padding-top: 0;
}

.footerCol p {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  margin: 0.5rem 0;
}

.footerCol a {
  color: var(--vt-accent-ink);
}

.footerCol a:hover {
  color: var(--vt-accent);
}

.copyright {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
  margin-top: 1rem;
}

/* Responsive */
@media (max-width: 991px) {
  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .heroSlider {
    height: inherit;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-bottom: 0;
    padding: 2rem;
  }

  .timelineNode {
    flex-direction: column;
    align-items: center;
  }

  .timelineNode:nth-child(even) {
    flex-direction: column;
  }

  .timeline::before {
    left: 50%;
    top: 60px;
    height: 90%;
  }

  .timelineContent {
    flex: 0 0 auto;
    width: 100%;
    max-width: 500px;
  }

  .timelineNode:nth-child(odd) h3,
  .timelineNode:nth-child(odd) p,
  .timelineNode:nth-child(even) h3,
  .timelineNode:nth-child(even) p {
    text-align: left;
  }

  .timelineNode:nth-child(odd) h3::after,
  .timelineNode:nth-child(even) h3::after {
    display: none;
  }

  .timelineIcon {
    margin: 1rem 0;
  }

  .timelineDate {
    flex: 0 0 auto;
    width: 100%;
    text-align: center !important;
    padding: 0.5rem 0;
  }
}

@media (max-width: 767px) {
  .navIn {
    flex-wrap: wrap;
    padding: 10px 15px;
  }

  .navLinks {
    width: 100%;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0.5rem;
    font-size: 0.875rem;
  }

  .container {
    padding: 0 10px;
  }

  .heroText {
    padding: 1.5rem;
  }

  .heroText h1 {
    font-size: 2rem;
  }

  .customLink {
    line-height: 35px;
    padding: 0 20px;
  }

  .galleryItem {
    flex: 0 0 100%;
  }

  .timeline::before {
    left: 40px;
  }

  .timelineIcon {
    margin-left: 15px;
  }

  .timelineContent {
    margin-left: 60px;
  }
}

@media (max-width: 575px) {
  .timeline::before {
    left: 30px;
  }

  .timelineContent {
    margin-left: 50px;
  }

  .timelineIcon {
    margin-left: 10px;
  }

  .timelineIcon span {
    width: 70px;
    height: 70px;
    font-size: 1.25rem;
  }
}
